insert into public.subjects (id,name,emoji,color,world_name,practice_marks,papers,exam_notes,sort,active,term) values ('ict','ICT','🤖','#22d3a6','Robot Foundry',60,'[{"name":"Written","marks":40,"duration":"1 h","date":"2026-11-20","time":"09:00"},{"name":"Practical","marks":20,"duration":"45 min","date":"2026-11-20","time":"11:15"}]'::jsonb,'Every ICT practice paper is 40 theory (Introduction to Robots) + 20 practical (flowcharts on paper + Scratch). Flowchart questions are drawn on paper (type ''diagram''). Scratch has no >= block. Robots follow their program exactly and cannot guess; avoid saying robots ''never make mistakes''. Dhruv tends to give half-answers on keyword-marked questions, so mark schemes must be keyword-strict.',4,true,'Grade 6 · Term 1 · 2026-27')
